// English word list for the spell corrector: 64,725 words (3 to 16 letters,
// inflections included; a proper noun only when common, like sunday or linux) from the system dictionary (SCOWL
// american-english), each with a frequency band 0-9: the higher of its count in ~200 MB of
// English documentation (GNOME help, info and man pages, /usr/share/doc) and in ~8 million words of
// public-domain books (Project Gutenberg), so everyday words (disease, budget) rank as common too.
// It tells the corrector which words are real, so "stand" is never "corrected"
// or split, and ranks candidates for ordinary English typos by how common they
// are. Front-coded: <shared-prefix length><rest><band letter B-J, none for 0>.
// Imports nothing.
const DATA = "";

let SET = null, FREQ = null;
function load() {
  SET = new Set(); FREQ = new Map();
  let prev = "";
  const re = /(\d)([a-z]+)([B-J]?)/g;
  let m;
  while ((m = re.exec(DATA))) {
    prev = prev.slice(0, +m[1]) + m[2];
    SET.add(prev);
    if (m[3]) FREQ.set(prev, m[3].charCodeAt(0) - 65);
  }
}
// Set of every word.
export function words() { if (!SET) load(); return SET; }
// Frequency band 0 (rare or unseen) .. 9 (the, and, for).
export function band(w) { if (!SET) load(); return FREQ.get(w) || 0; }
